SELECT m.CSNAME AS `股票名称`, m.COMB_SYMBOL AS `股票代码`, ROUND(c1.F048N / 100, 3) AS `2025财年营业收入(亿美元)`, ROUND(c2.F048N / 100, 3) AS `2024财年营业收入(亿美元)`, ROUND((c1.F048N - c2.F048N) / NULLIF(c2.F048N, 0) * 100, 2) AS `营业收入同比增长率(%)`, c1.F005V AS `货币` FROM AMERICAN_STOCK_MAIN m INNER JOIN VIEW_COM3103_CUM c1 ON m.FIU_ID = c1.FIU_ID INNER JOIN VIEW_COM3103_CUM c2 ON m.FIU_ID = c2.FIU_ID WHERE m.CSNAME LIKE '%苹果%' AND c1.F056N = 2025 AND c1.F003V = 'FY' AND c1.F048N IS NOT NULL AND c1.F001D IS NOT NULL AND c2.F056N = 2024 AND c2.F003V = 'FY' AND c2.F048N IS NOT NULL AND c2.F001D IS NOT NULL ORDER BY c1.F001D DESC LIMIT 1;
